                                    authorities: [Authority.EDITOR, Authority.INSTRUCTOR, Authority.ADMIN],
                                    pageTitle: 'global.generic.edit',
                                },
                                canActivate: [UserRouteAccessService],
                            },
                            ...lectureUnitRoute,
                        ],
                    },
                ],
            },
        ],
    },
];
